//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$email  = trim($values["email"]);
$nombre = trim($values["nombre"]);

// 1. Validar nombre mínimo
if (strlen($nombre) < 3) {
    $message = "El nombre del usuario debe contener al menos 3 caracteres.";
    return false;
}

// 2. Validar formato de correo
if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
    $message = "La dirección de correo electrónico <strong>" . htmlspecialchars($email) . "</strong> no tiene un formato válido.";
    return false;
}

// 3. Validar correo único
$rsEmail = DB::Query("SELECT id FROM usuarios WHERE LOWER(email) = LOWER(" . db_prepare_string($email) . ") LIMIT 1");
if ($rsEmail->fetchAssoc()) {
    $message = "El correo electrónico <strong>" . htmlspecialchars($email) . "</strong> ya se encuentra registrado.";
    return false;
}

// 4. Valores por defecto
if (empty($values["creado_en"])) {
    $values["creado_en"] = date("Y-m-d H:i:s");
}
if (empty($values["activo"])) {
    $values["activo"] = "Sí";
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record updated
function BeforeEdit(&$values, $where, &$oldvalues, &$keys, &$message, $inline, &$pageObject)
{

		$id_actual = isset($keys["id"]) ? intval($keys["id"]) : 0;
$email     = trim($values["email"]);
$nombre    = trim($values["nombre"]);

if (strlen($nombre) < 3) {
    $message = "El nombre del usuario debe contener al menos 3 caracteres.";
    return false;
}

if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
    $message = "El correo electrónico no tiene un formato válido.";
    return false;
}

$rsEmail = DB::Query("SELECT id FROM usuarios WHERE LOWER(email) = LOWER(" . db_prepare_string($email) . ") AND id != " . $id_actual . " LIMIT 1");
if ($rsEmail->fetchAssoc()) {
    $message = "El correo electrónico ya pertenece a otro usuario.";
    return false;
}

return true;
;		
} // function BeforeEdit

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record deleted
function BeforeDelete($where, &$deleted_values, &$message, &$pageObject)
{

		$usr_id = intval($deleted_values["id"]);

// Proteger si es alumno
$rsEst = DB::Query("SELECT id FROM estudiantes WHERE usuario_id = " . $usr_id . " LIMIT 1");
if ($rsEst->fetchAssoc()) {
    $message = "No se puede eliminar el usuario porque está vinculado a un legajo de estudiante.";
    return false;
}

// Proteger si es docente
$rsProf = DB::Query("SELECT id FROM profesores WHERE usuario_id = " . $usr_id . " LIMIT 1");
if ($rsProf->fetchAssoc()) {
    $message = "No se puede eliminar el usuario porque está vinculado a un docente.";
    return false;
}

return true;
;		
} // function BeforeDelete

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



